def txt(node):
    if isinstance(node,dict):
        if node.get('type')=='text': return node.get('text','')
        if 'inlineContent' in node: return ''.join(txt(x) for x in node['inlineContent'])
        if 'content' in node: return ''.join(txt(x) for x in node['content'])
        if node.get('type')=='reference': return '[REF:'+str(node.get('identifier'))+']'
        if node.get('type')=='image': return '[IMG:'+str(node.get('identifier'))+']'
        if node.get('type')=='items' or 'items' in node: return '\n'.join(txt(x) for x in node.get('items',[]))
        return ''
